import sizes from "./media-sizes.json" with { type: "json" };

const table = sizes as unknown as Record<string, [number, number]>;

/** A project image's intrinsic [width, height] (generated by scripts/media-colors.mjs), so its box is held before it loads. */
export function mediaSize(src: string): [number, number] | undefined {
  return table[src];
}
